globalCss:
.scene {
  --petala: #F6F3FB;
  --lilas: #ECE6F8;
  --agua-mapa: #E0D9F1;
  --rule: #DCD3EE;
  --tinta: #221B33;
  --tinta-2: #5D5470;
  --jaca: #5B3FA8;
  --jaca-claro: #B9A4EE;
  --folha: #27704C;
  --atencao: #F2C230;
  --perigo: #E8731C;
  --grande: #C62828;
  --contexto: #8E80B8;
  --noite-texto: #F6F3FB;
  --noite-2: #B8AECF;
  --noite-rule: #3A3150;
  --titulo: 'Sora', system-ui, sans-serif;
  --texto: 'Figtree', system-ui, sans-serif;

  position: relative;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  box-sizing: border-box;
  padding: 88px 128px 0;
  background: var(--petala);
  color: var(--tinta);
  font: 400 30px/1.4 var(--texto);
  -webkit-font-smoothing: antialiased;
}
.scene *, .scene *::before, .scene *::after { box-sizing: border-box; }
.scene p, .scene h1, .scene h2, .scene h3, .scene ul, .scene ol, .scene figure { margin: 0; padding: 0; }
.scene ul, .scene ol { list-style: none; }
.scene .num { font-variant-numeric: tabular-nums; }
.scene.tone-tinta { background: var(--tinta); color: var(--noite-texto); }

/* header: pin + section name, then the title. Top right stays empty (speaker tag). */
.scene .sec { display: flex; align-items: center; gap: 16px; font: 500 24px/1 var(--texto); color: var(--tinta-2); }
.scene .sec svg { width: 22px; height: 28px; }
.scene.tone-tinta .sec { color: var(--noite-2); --pin-dot: #5B3FA8; }
.scene .title { text-wrap: balance; margin-top: 24px; max-width: 1200px; font: 700 72px/1.05 var(--titulo); letter-spacing: -.02em; }
.scene .body { position: absolute; left: 128px; right: 128px; top: 288px; bottom: 96px; }
.scene .note { position: absolute; left: 128px; right: 128px; bottom: 40px; font: 400 20px/1.3 var(--texto); color: var(--tinta-2); }
.scene.tone-tinta .note { color: var(--noite-2); }
.scene .label { font: 500 24px/1.3 var(--texto); color: var(--tinta-2); }
.scene .big { font: 800 200px/.9 var(--titulo); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
.scene mark { color: inherit; padding: 0 .06em; white-space: nowrap; background: linear-gradient(var(--lilas), var(--lilas)) no-repeat 0 100% / var(--hl, 100%) .42em; }
.scene.tone-tinta mark { background: none; color: color-mix(in srgb, var(--jaca-claro) var(--hl, 100%), var(--noite-texto)); }

/* app icon on a colored disc, like the app's occurrence badges */
.scene .ic { display: grid; place-items: center; border-radius: 50%; }
.scene .ic svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }

/* phone frame for app takes: bezel in Tinta, screen radius of the device */
.scene .phone { position: absolute; padding: 14px; border-radius: 64px; background: var(--tinta); }
.scene .phone img, .scene .phone video { display: block; width: 100%; height: 100%; object-fit: cover; object-position: top; border-radius: 50px; }

/* --- s01 A torneira seca ------------------------------------------------- */
/* The chain the whole pitch follows, drawn with the app's own icons. Spacing is time: the light goes
   right after the storm; the water runs out hours later (long dashed wait). */
.s-torneira .cadeia { position: absolute; left: 0; top: 24px; width: 1664px; height: 240px; }
.s-torneira .cadeia > svg { position: absolute; left: 0; top: 0; overflow: visible; }
.s-torneira .fio { stroke: var(--noite-2); stroke-width: 3; fill: none; }
.s-torneira .cadeia > svg.espera { position: absolute; left: 640px; top: 46px; width: 904px; height: 4px; }
.s-torneira .espera path { stroke: var(--noite-2); stroke-width: 3; stroke-dasharray: 12 12; fill: none; }
.s-torneira .disc.d-chuva { background: var(--contexto); color: #fff; }
.scene.s-torneira .tag { top: 128px; width: 400px; color: var(--noite-2); }
.scene.s-torneira .tag h3 { color: var(--noite-texto); }
.s-torneira .tag.right { text-align: right; }
.s-torneira .horas { position: absolute; left: 640px; top: 72px; width: 904px; text-align: center; font: 500 26px/1.2 var(--texto); color: var(--noite-2); }
.s-torneira .depois { text-wrap: balance; position: absolute; left: 0; top: 336px; max-width: 1560px; font: 600 64px/1.18 var(--titulo); letter-spacing: -.02em; color: var(--noite-2); }
.s-torneira .depois b { color: var(--noite-texto); font-weight: 800; }
.s-torneira .depois .ag { color: var(--jaca-claro); font-weight: 700; }
/* Opening: the path and the three stops show first as outlines (in on "Porto Alegre"), and each stop lights up on its word. */
.s-torneira .cadeia > svg.trilho { position: absolute; left: 48px; top: 46px; width: 1568px; height: 4px; }
.s-torneira .trilho path { stroke: var(--noite-rule); stroke-width: 3; fill: none; }
.s-torneira .vazio { position: absolute; top: 0; width: 96px; height: 96px; border-radius: 50%; border: 2px solid var(--noite-rule); background: var(--tinta); display: grid; place-items: center; color: var(--noite-rule); }
.s-torneira .vazio svg { width: 48px; height: 48px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.s-torneira .bombas { position: absolute; left: 0; top: 560px; font: 400 30px/1.35 var(--texto); color: var(--noite-2); }

/* --- s04 A prova nos dados ------------------------------------------------ */
.s-dados .total { position: absolute; left: 0; top: 0; width: 456px; }
.s-dados .total b { display: block; font: 800 96px/1 var(--titulo); letter-spacing: -.03em; color: var(--jaca); font-variant-numeric: tabular-nums; }
.s-dados .total p { text-wrap: balance; margin-top: 32px; font: 400 30px/1.35 var(--texto); }
.s-dados .total p span { display: block; margin-top: 8px; font-size: 24px; color: var(--tinta-2); }
.s-dados .chart { position: absolute; left: 600px; top: -24px; width: 1064px; height: 640px; }
.s-dados .chart svg { overflow: visible; }
.s-dados .bars-ctx { fill: var(--contexto); }
.s-dados .bars-hot { fill: var(--jaca); }
.s-dados .base { stroke: var(--tinta-2); stroke-width: 1; }
.s-dados .bracket { fill: none; stroke: var(--tinta); stroke-width: 2; }
.s-dados .bracket.rest { stroke: var(--tinta-2); }
.s-dados .pct { position: absolute; font: 700 44px/1 var(--titulo); letter-spacing: -.01em; white-space: nowrap; }
.s-dados .pct small { font: 500 24px/1 var(--texto); color: var(--tinta-2); margin-left: 12px; letter-spacing: 0; }
.s-dados .pct.rest { color: var(--tinta-2); }
.s-dados .first { position: absolute; left: 32px; top: 76px; font: 500 20px/1.25 var(--texto); color: var(--tinta-2); white-space: nowrap; }
.s-dados .first b { color: var(--tinta); font-weight: 600; }
.s-dados .names { position: absolute; left: 0; top: 544px; font: 500 24px/1.3 var(--texto); }
.s-dados .axis { position: absolute; left: 0; top: 600px; font: 400 20px/1.3 var(--texto); color: var(--tinta-2); }

/* --- s07 O efeito cascata --------------------------------------------------- */
/* Spacing encodes time: the first four events happen within minutes, the water runs out hours later. */
.s-cascata .line { position: absolute; left: 0; top: 64px; width: 1120px; height: 560px; }
.s-cascata .line > svg { position: absolute; left: 0; top: 0; overflow: visible; }
.s-cascata .axis { stroke: var(--tinta-2); stroke-width: 2; fill: none; }
.s-cascata .axis.wait { stroke-dasharray: 10 10; }
.s-cascata .gap { stroke: var(--folha); stroke-width: 3; fill: none; }
.s-cascata .ev { position: absolute; width: 64px; height: 64px; margin: -32px 0 0 -32px; top: 216px; color: #fff; }
.s-cascata .ev svg { width: 32px; height: 32px; }
.s-cascata .lb { position: absolute; width: 240px; font: 400 24px/1.3 var(--texto); color: var(--tinta-2); }
.s-cascata .lb h3 { font: 700 30px/1.15 var(--titulo); letter-spacing: -.01em; color: var(--tinta); margin-bottom: 4px; }
.s-cascata .lb.up { bottom: 400px; }
.s-cascata .lb.down { top: 272px; }
.s-cascata .lb.right { text-align: right; }
.s-cascata .e-luz { background: var(--grande); }
.s-cascata .e-conf { background: var(--jaca); }
.s-cascata .e-est, .s-cascata .e-aviso { background: var(--folha); }
.s-cascata .e-agua { background: var(--perigo); color: var(--tinta); }
.s-cascata .prep { position: absolute; left: 440px; top: 476px; width: 600px; text-align: center; font: 600 30px/1.2 var(--texto); color: var(--folha); }
.s-cascata .phone { right: 128px; top: 232px; width: 372px; height: 792px; }

/* --- shared: event discs and wires (s02, s07, s09 use the same marks) ----------- */
.scene .disc { position: absolute; width: 96px; height: 96px; color: #fff; }
.scene .disc svg { width: 48px; height: 48px; }
.scene .disc.sm { width: 64px; height: 64px; }
.scene .disc.sm svg { width: 32px; height: 32px; }
.scene .d-luz { background: var(--grande); }
.scene .d-conf { background: var(--jaca); }
.scene .d-est, .scene .d-aviso { background: var(--folha); }
.scene .d-agua { background: var(--perigo); color: var(--tinta); }
.scene .wire { stroke: var(--tinta-2); stroke-width: 2; fill: none; }
.scene .wire.wait { stroke-dasharray: 10 10; }
.scene .gapline { stroke: var(--folha); stroke-width: 3; fill: none; }
.scene .tag { position: absolute; font: 400 24px/1.3 var(--texto); color: var(--tinta-2); }
.scene .tag h3 { font: 700 30px/1.15 var(--titulo); letter-spacing: -.01em; color: var(--tinta); margin-bottom: 4px; }
.scene .rule { border-top: 1px solid var(--rule); }

/* app severity badges, exactly as the app draws them: color plus the written word */
.scene .selo { display: inline-block; padding: 8px 20px; border-radius: 999px; font: 700 24px/1 var(--titulo); }
.scene .selo.at { background: var(--atencao); color: #3A2C00; }
.scene .selo.pe { background: var(--perigo); color: #2B1200; }
.scene .selo.gp { background: var(--grande); color: #fff; }

/* browser frame for the desktop screens: same bezel language as the phone */
.scene .browser { position: absolute; padding: 12px; border-radius: 24px; background: var(--tinta); }
.scene .browser img { display: block; width: 100%; height: auto; border-radius: 12px; }

/* --- s02 Por que acontece -------------------------------------------------- */
.s-porque .diagram { position: absolute; left: 0; top: 0; width: 1664px; height: 320px; }
.s-porque .diagram > svg { position: absolute; left: 0; top: 0; overflow: visible; }
.s-porque .tag { top: 128px; width: 400px; }
.s-porque .frase { position: absolute; left: 0; top: 344px; font: 600 56px/1.2 var(--titulo); letter-spacing: -.02em; }
.s-porque .viv { position: absolute; left: 0; top: 512px; max-width: 1200px; font: 400 30px/1.4 var(--texto); color: var(--tinta-2); }
.s-porque .viv b { color: var(--tinta); font-weight: 600; }

/* --- s03 Quem sofre -------------------------------------------------------- */
.s-quem .q { position: absolute; left: 0; font: 600 56px/1.2 var(--titulo); letter-spacing: -.02em; }
.s-quem .q span { color: var(--jaca); }
.s-quem .rule { position: absolute; left: 0; right: 0; top: 248px; }
.s-quem .pesa { text-wrap: balance; position: absolute; left: 0; top: 296px; max-width: 1480px; font: 400 40px/1.35 var(--texto); }
.s-quem .hoje { position: absolute; left: 0; top: 520px; max-width: 1200px; font: 400 30px/1.4 var(--texto); color: var(--tinta-2); }

/* --- s05 Alertaí (brand moment, Jacarandá) -------------------------------- */
.scene.tone-jaca { background: var(--jaca); color: #fff; }
.s-alertai .logo { position: absolute; left: 128px; top: 120px; width: 476px; height: 120px; }
.s-alertai .pergunta { text-wrap: balance; position: absolute; left: 128px; top: 368px; width: 1180px; font: 700 72px/1.1 var(--titulo); letter-spacing: -.02em; }
.s-alertai .sub { text-wrap: balance; position: absolute; left: 128px; top: 720px; width: 1080px; font: 400 30px/1.4 var(--texto); color: var(--lilas); }
.s-alertai .phone { right: 128px; top: 144px; width: 372px; height: 792px; }

/* --- s05m O mapa (review of 18/11: every risk, bairro by bairro) ------------- */
/* João's own recording of the Mapa ao vivo plays in the browser frame (1135x680 crop of the app, no
   sidebar); the right column says what the map shows, each line on its word. */
.s-mapa .browser { left: 128px; top: 288px; width: 1092px; }
.s-mapa .browser img { height: 640px; object-fit: cover; object-position: top; }
.s-mapa .riscos { position: absolute; left: 1156px; top: 0; width: 508px; }
.s-mapa .riscos li { padding: 24px 0; border-top: 1px solid var(--rule); }
.s-mapa .riscos li:first-child { border-top: 0; padding-top: 0; }
.s-mapa .riscos h3 { font: 700 36px/1.15 var(--titulo); letter-spacing: -.01em; }
.s-mapa .riscos p { margin-top: 8px; font: 400 26px/1.35 var(--texto); color: var(--tinta-2); }

/* --- s06 Como funciona ------------------------------------------------------- */
.s-funciona .passos { position: absolute; left: 0; top: 0; width: 1120px; }
.s-funciona .passos li { display: grid; grid-template-columns: 72px 1fr; padding: 32px 0; border-top: 1px solid var(--rule); }
.s-funciona .passos li:first-child { border-top: 0; padding-top: 0; }
.s-funciona .passos b { font: 800 44px/1 var(--titulo); color: var(--jaca); }
.s-funciona .passos h3 { font: 700 40px/1.15 var(--titulo); letter-spacing: -.01em; }
.s-funciona .passos p { margin-top: 8px; font: 400 28px/1.35 var(--texto); color: var(--tinta-2); }
.s-funciona .fonte { position: absolute; left: 72px; top: 600px; width: 1048px; font: 600 30px/1.3 var(--texto); color: var(--folha); }
.s-funciona .phone { right: 128px; top: 232px; width: 372px; height: 792px; }

/* --- s08 O protótipo -------------------------------------------------------- */
.s-proto .strip { position: absolute; left: 0; display: flex; gap: 16px; }
.s-proto .strip img { width: 120px; height: 260px; object-fit: cover; object-position: top; border-radius: 12px; border: 1px solid var(--rule); }
.s-proto .lbl { position: absolute; left: 0; font: 500 24px/1.2 var(--texto); color: var(--tinta-2); }
.s-proto .browser { left: 1040px; top: 40px; width: 504px; }
.s-proto .acess { position: absolute; left: 1040px; top: 392px; width: 624px; }
.s-proto .acess li { padding: 12px 0; border-top: 1px solid var(--rule); font: 400 24px/1.35 var(--texto); color: var(--tinta-2); }
.s-proto .acess li:first-child { border-top: 0; padding-top: 0; }
.s-proto .acess li.selos .row { display: flex; gap: 16px; margin-bottom: 8px; }
.s-proto .acess b { color: var(--tinta); font-weight: 600; }

/* --- s09 Como medir ---------------------------------------------------------- */
.s-medir .central { position: absolute; left: 0; top: 0; width: 840px; }
.s-medir .central h3 { font: 700 56px/1.1 var(--titulo); letter-spacing: -.02em; }
.s-medir .central p { margin-top: 16px; font: 400 30px/1.35 var(--texto); color: var(--tinta-2); }
.s-medir .mini { position: absolute; left: 0; top: 248px; width: 840px; height: 300px; }
.s-medir .mini > svg { position: absolute; left: 0; top: 0; overflow: visible; }
.s-medir .meta { position: absolute; left: 32px; top: 168px; width: 744px; text-align: center; font: 700 44px/1 var(--titulo); color: var(--folha); }
.s-medir .meta small { font: 500 26px/1 var(--texto); margin-right: 12px; }
.s-medir .outros { position: absolute; left: 1000px; top: 0; width: 664px; }
.s-medir .outros li { padding: 32px 0; border-top: 1px solid var(--rule); }
.s-medir .outros li:first-child { border-top: 0; padding-top: 0; }
.s-medir .outros h3 { font: 700 40px/1.15 var(--titulo); letter-spacing: -.01em; }
.s-medir .outros p { margin-top: 8px; font: 400 26px/1.35 var(--texto); color: var(--tinta-2); }
.s-medir .outros p b { color: var(--tinta); font-weight: 600; }

/* --- s10 ODS e próximo passo ------------------------------------------------ */
.s-ods .lista { position: absolute; left: 0; top: 0; width: 880px; }
.s-ods .lista li { display: grid; grid-template-columns: 88px 1fr; column-gap: 24px; align-items: center; padding: 24px 0; border-top: 1px solid var(--rule); }
.s-ods .lista li:first-child { border-top: 0; padding-top: 0; }
.s-ods .n { display: grid; place-items: center; width: 88px; height: 88px; border-radius: 16px; font: 800 44px/1 var(--titulo); }
.s-ods .lista h3 { font: 700 28px/1.2 var(--titulo); }
.s-ods .lista p { margin-top: 4px; font: 400 24px/1.35 var(--texto); color: var(--tinta-2); }
.s-ods .mapa { position: absolute; left: 980px; top: 0; width: 684px; }
.s-ods .mapa svg { display: block; overflow: visible; }
/* white halo behind map labels, like the label boxes in the app map */
.s-ods .maplbl, .s-ods .maplbl text { paint-order: stroke; stroke: #fff; stroke-width: 5px; stroke-linejoin: round; }
.s-ods .mapa .cap { margin-top: 16px; font: 400 20px/1.3 var(--texto); color: var(--tinta-2); }

/* --- s11 Assinatura ----------------------------------------------------------- */
.s-fim .logo { position: absolute; left: 128px; top: 200px; width: 476px; height: 120px; }
.s-fim .frase { position: absolute; left: 128px; top: 424px; width: 1500px; font: 700 96px/1.05 var(--titulo); letter-spacing: -.03em; }
.s-fim .frase span { color: var(--jaca-claro); }
.s-fim .equipe { text-wrap: balance; position: absolute; left: 128px; top: 768px; width: 1664px; font: 400 26px/1.5 var(--texto); color: var(--noite-2); }
.s-fim .equipe b { color: var(--noite-texto); font-weight: 600; }
.s-fim .equipe .nm { white-space: nowrap; }  /* a line may break between two people, never inside a name */
